let themeToggle = document.querySelector("#themeToggle");
let body = document.body;

// Загрузка темы при старте
let savedTheme = localStorage.getItem("theme");
if (savedTheme) {
    body.classList.add(savedTheme);
}

// Переключение темы
themeToggle.addEventListener("click", function() {
    body.classList.toggle("dark");
    let isDark = body.classList.contains("dark");
    localStorage.setItem("theme", isDark ? "dark" : "light");
});

let user = { name: "Анна", age: 25, hobbies: ["чтение", "программирование"] };

// Сохранение:
localStorage.setItem("user", JSON.stringify(user));

// Получение:
let savedUser = JSON.parse(localStorage.getItem("user"));
console.log(savedUser.name); // "Анна"
console.log(savedUser.hobbies); // ["чтение", "программирование"]

const Storage = {
    prefix: "myapp_",

    set(key, value) {
        localStorage.setItem(this.prefix + key, JSON.stringify(value));
    },

    get(key) {
        const data = localStorage.getItem(this.prefix + key);
        return data ? JSON.parse(data) : null;
    },

    remove(key) {
        localStorage.removeItem(this.prefix + key);
    }
};

Storage.set("user", { name: "Анна" });
Storage.get("user"); // { name: "Анна" }
